from pathlib import Path
Path('system').mkdir(exist_ok=True); Path('constant').mkdir(exist_ok=True)
header=lambda cls,obj: f'''FoamFile
{{
    format ascii;
    class {cls};
    object {obj};
}}
'''
block = header('dictionary','blockMeshDict') + '''convertToMeters 1;
vertices
(
 (-0.008 -0.004 -0.004)
 ( 0.168 -0.004 -0.004)
 ( 0.168  0.108 -0.004)
 (-0.008  0.108 -0.004)
 (-0.008 -0.004  0.044)
 ( 0.168 -0.004  0.044)
 ( 0.168  0.108  0.044)
 (-0.008  0.108  0.044)
);
blocks ( hex (0 1 2 3 4 5 6 7) (22 14 6) simpleGrading (1 1 1) );
edges ();
boundary
(
 background { type patch; faces ((0 4 7 3)(1 2 6 5)(0 1 5 4)(3 7 6 2)(0 3 2 1)(4 5 6 7)); }
);
mergePatchPairs ();
'''
Path('system/blockMeshDict').write_text(block)
tri_names=['open_top','vent','enclosure_walls_floor','standoff_outer','blind_holes']
geom='
'.join([f'''    {n}.stl
    {{
        type triSurfaceMesh;
        name {n};
    }}''' for n in tri_names])
refs=[]
for n in tri_names:
    lev='(2 3)' if n in ('standoff_outer','blind_holes') else '(1 2)'
    typ='patch' if n in ('open_top','vent') else 'wall'
    refs.append(f'''        {n}
        {{
            level {lev};
            patchInfo {{ type {typ}; }}
        }}''')
snappy=header('dictionary','snappyHexMeshDict')+f'''castellatedMesh true;
snap true;
addLayers false;
geometry
{{
{geom}
}}
castellatedMeshControls
{{
    maxLocalCells 200000;
    maxGlobalCells 500000;
    minRefinementCells 0;
    nCellsBetweenLevels 2;
    features ();
    refinementSurfaces
    {{
{chr(10).join(refs)}
    }}
    resolveFeatureAngle 30;
    refinementRegions {{}}
    locationInMesh (0.080 0.050 0.035);
    allowFreeStandingZoneFaces true;
}}
snapControls
{{
    nSmoothPatch 3;
    tolerance 2.0;
    nSolveIter 50;
    nRelaxIter 5;
    nFeatureSnapIter 10;
    implicitFeatureSnap true;
    explicitFeatureSnap false;
    multiRegionFeatureSnap false;
}}
addLayersControls {{ relativeSizes true; layers {{}} expansionRatio 1.0; finalLayerThickness 0.3; minThickness 0.1; nGrow 0; featureAngle 60; nRelaxIter 3; nSmoothSurfaceNormals 1; nSmoothNormals 3; nSmoothThickness 10; maxFaceThicknessRatio 0.5; maxThicknessToMedialRatio 0.3; minMedialAxisAngle 90; nBufferCellsNoExtrude 0; nLayerIter 50; }}
meshQualityControls
{{
    #include "meshQualityDict"
}}
debug 0;
mergeTolerance 1e-6;
'''
Path('system/snappyHexMeshDict').write_text(snappy)
control=header('dictionary','controlDict')+'''application snappyHexMesh;
startFrom startTime; startTime 0; stopAt endTime; endTime 1; deltaT 1; writeControl timeStep; writeInterval 1; purgeWrite 0; writeFormat ascii; writePrecision 8; writeCompression off; timeFormat general; timePrecision 6; runTimeModifiable true;
'''
Path('system/controlDict').write_text(control)
print('Wrote blockMeshDict, snappyHexMeshDict, controlDict; background cells =',22*14*6)

